-- Solo se ejecuta en el contenedor aislado de test-stock-locales.cjs.
CREATE ROLE authenticated;
CREATE ROLE anon;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth TO authenticated,anon;
CREATE TABLE public.finanzas_accesos(user_id uuid PRIMARY KEY);
INSERT INTO public.finanzas_accesos VALUES ('00000000-0000-4000-8000-000000000001');
CREATE TABLE public.insumos(id uuid PRIMARY KEY,nombre text,categoria text,stock_actual numeric,stock_minimo numeric DEFAULT 0);
CREATE TABLE public.kits(id uuid PRIMARY KEY,nombre text,precio_venta numeric,activo boolean);
CREATE TABLE public.puntos_entrega(id uuid PRIMARY KEY);
CREATE TABLE public.recetas_kit(id uuid PRIMARY KEY,kit_id uuid,insumo_id uuid,cantidad numeric);
CREATE TABLE public.compras_insumos(id uuid PRIMARY KEY,insumo_id uuid,cantidad numeric,fecha date,costo_unitario numeric,costo_total numeric,metodo_pago text);
CREATE TABLE public.movimientos_inventario(id uuid PRIMARY KEY,insumo_id uuid,cantidad numeric,tipo_movimiento text);
CREATE TABLE public.pedidos(id uuid PRIMARY KEY,estatus text,fecha_entrega date,created_at timestamptz,punto_entrega_id uuid,metodo_pago text,eliminado boolean);
CREATE TABLE public.pedido_kits(id uuid PRIMARY KEY,pedido_id uuid,kit_id uuid,cantidad numeric,precio_unitario numeric,subtotal numeric);
CREATE TABLE public.pedido_kit_receta(id uuid PRIMARY KEY,pedido_kit_id uuid,insumo_id uuid,cantidad numeric);
CREATE TABLE public.ventas_local(id uuid PRIMARY KEY,punto_entrega_id uuid,fecha date,ingreso_total numeric,comision_monto numeric,metodo_pago text);
CREATE TABLE public.ventas_local_kits(id uuid PRIMARY KEY,venta_local_id uuid,kit_id uuid,cantidad numeric);
CREATE TABLE public.inventario_kits_local(id uuid PRIMARY KEY,punto_entrega_id uuid,kit_id uuid,cantidad numeric,updated_at timestamptz DEFAULT now());
CREATE TABLE public.movimientos_kits_local(id uuid PRIMARY KEY,punto_entrega_id uuid,kit_id uuid,tipo text,cantidad numeric,fecha date,motivo text,venta_local_id uuid,notas text);
CREATE TABLE public.gastos(id uuid PRIMARY KEY,concepto text,fecha date,monto numeric,categoria text,metodo_pago text,notas text);
CREATE TABLE public.saldos_cuenta(metodo_pago text PRIMARY KEY,saldo_inicial numeric);
CREATE TABLE public.ingresos_extra(id uuid PRIMARY KEY,concepto text,fecha date,monto numeric,metodo_pago text,notas text);
