INSERT INTO public.pedido_kit_receta SELECT gen_random_uuid(),pk.id,r.insumo_id,r.cantidad FROM public.pedido_kits pk JOIN public.recetas_kit r ON r.kit_id=pk.kit_id;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT UPDATE ON public.inventario_kits_local TO authenticated;
GRANT INSERT ON public.movimientos_kits_local TO authenticated;
ALTER TABLE public.finanzas_accesos ENABLE ROW LEVEL SECURITY;
CREATE POLICY propio ON public.finanzas_accesos TO authenticated USING (user_id=auth.uid());
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename<>'finanzas_accesos' LOOP
EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t.tablename);
EXECUTE format('CREATE POLICY equipo ON public.%I TO authenticated USING (EXISTS(SELECT 1 FROM public.finanzas_accesos WHERE user_id=auth.uid())) WITH CHECK (EXISTS(SELECT 1 FROM public.finanzas_accesos WHERE user_id=auth.uid()))',t.tablename);
END LOOP; END $$;
